-- supabase/sql/exam_question_bank_neet_ug_set5.sql
--
-- Fifth curated question-bank batch for 'NEET UG' (see exam_patterns_neet_ug.sql for the exam's
-- structure, and Sets 1-4 for the earlier batches -- same table/schema, no migration needed).
-- All-new questions, no overlap with Sets 1, 2, 3, or 4.
--
-- Same format as the earlier sets: every row is format='mcq' with a single isCorrect:true option,
-- matching NEET UG's 100% single-best-response format. 16 chapters (4 each across Physics,
-- Chemistry, Botany, Zoology) each get 4 questions.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_neet_ug.sql and
-- exam_question_bank_neet_ug_set1.sql through set4.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Physics: Mechanics
('NEET UG', 'Physics', 'Mechanics', 'medium', 'mcq',
 'The dimensional formula of angular momentum is:',
 '[{"text":"[MLT^-1]","isCorrect":false},{"text":"[ML^2T^-1]","isCorrect":true},{"text":"[ML^2T^-2]","isCorrect":false},{"text":"[MLT^-2]","isCorrect":false}]'::jsonb,
 null, 'Angular momentum L = I*omega has dimensions [ML^2]*[T^-1] = [ML^2T^-1].'),
('NEET UG', 'Physics', 'Mechanics', 'easy', 'mcq',
 'A body moving in uniform circular motion has constant:',
 '[{"text":"Velocity","isCorrect":false},{"text":"Speed (and kinetic energy)","isCorrect":true},{"text":"Acceleration direction","isCorrect":false},{"text":"Displacement","isCorrect":false}]'::jsonb,
 null, 'In uniform circular motion, the speed (and hence kinetic energy) remains constant, even though the velocity''s direction is continuously changing.'),
('NEET UG', 'Physics', 'Mechanics', 'medium', 'mcq',
 'The coefficient of static friction between two surfaces is generally:',
 '[{"text":"Less than the coefficient of kinetic friction","isCorrect":false},{"text":"Greater than or equal to the coefficient of kinetic friction","isCorrect":true},{"text":"Always exactly zero","isCorrect":false},{"text":"Unrelated to the coefficient of kinetic friction","isCorrect":false}]'::jsonb,
 null, 'The coefficient of static friction is generally greater than or equal to the coefficient of kinetic friction, since more force is typically needed to start motion than to sustain it.'),
('NEET UG', 'Physics', 'Mechanics', 'medium', 'mcq',
 'According to the work-energy theorem, negative work done on an object results in:',
 '[{"text":"An increase in its kinetic energy","isCorrect":false},{"text":"A decrease in its kinetic energy","isCorrect":true},{"text":"No change in its kinetic energy","isCorrect":false},{"text":"An increase in its mass","isCorrect":false}]'::jsonb,
 null, 'Since work done equals the change in kinetic energy, negative work (such as from a retarding force) causes a decrease in an object''s kinetic energy.'),

